package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AuthorizationSignedResponseAlgVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property authorization signed response alg of oauth client ")
  void test_authorization_signed_response_alg_v_o_builder() {
    Assertions.assertFalse(AuthorizationSignedResponseAlgVO.nullValue()
        .getAuthorizationSignedResponseAlg().isPresent(), "A empty vo should have a null value");
    Assertions.assertFalse(AuthorizationSignedResponseAlgVO.tryFrom(null)
        .getAuthorizationSignedResponseAlg().isPresent(), "With a null value, no present result");
    Assertions.assertEquals("one", AuthorizationSignedResponseAlgVO.from("one")
        .getAuthorizationSignedResponseAlg().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AuthorizationSignedResponseAlgVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        AuthorizationSignedResponseAlgVO.from("one").toString());
  }
}
